let medaglioneN = 0;
function medaglione(nome, misura = 42){
  const id = 'm' + (++medaglioneN).toString(36);
  return '<svg class="med" width="' + misura + '" height="' + misura + '" viewBox="0 0 56 56" aria-hidden="true">' + (MEDAGLIONI[nome] || MEDAGLIONI.effetto).replace(/__ID__/g, id) + '</svg>';
}
/* un effetto o un sottofondo senza disegno suo: si riconosce dal nome (come medaglioneDaNome di DMaster) */
const PAROLE_MED = [
  [/tavern|locand|osteria|boccal/i, 'boccale'], [/bosc|forest|alber|fronde|selv/i, 'albero'], [/grott|cavern|minier|cunicol/i, 'grotta'],
  [/castell|sala del|trono|corte/i, 'castello'], [/mare|onde|porto|fium|ruscell|rane|lago|cascat/i, 'onda'], [/campan|abbazi|chies|monaster|sacro|canti/i, 'campana'],
  [/civett|gufo|allocc/i, 'civetta'], [/uccell|cucul|allodol|gabbian|rapace|falco|merl|passer/i, 'uccello'], [/grill|cical/i, 'grillo'],
  [/mercat|fiera|piazza|citt|borgo|villagg/i, 'mercato'], [/cript|tomb|sepolcr|candel|catacomb/i, 'candela'], [/stormo/i, 'stormo'],
  [/port[ae]|uscio|portone/i, 'porta'], [/pass[io]|stivali|cammin/i, 'passi'], [/spad[ae]|lam[ae]|acciaio/i, 'spade'],
  [/frecc|arco\b|dardo/i, 'frecce'], [/scud/i, 'scudo'], [/fuoco|fiamm|legna|brace|camino|taverna|locanda/i, 'fuoco'], [/lup[oi]|ringh|bestia|ulul/i, 'ringhio'],
  [/magi|incant|sortileg/i, 'magia'], [/tuon|lamp|fulmin|tempest/i, 'lampo'], [/vento|raffic|imposte/i, 'raffica'], [/scrign|forziere|monet/i, 'scrigno'],
  [/ingranag|meccanism|catena/i, 'meccanismo'], [/pietra|macign|lastra/i, 'pietra'], [/chiave|serratura|lucchetto|clic/i, 'clic'],
  [/grid|urlo|urla/i, 'grido'], [/piogg/i, 'pioggia'], [/nebbi/i, 'nebbia'], [/nev/i, 'neve'],
];
function medaglioneDaNome(nome, altrimenti = 'effetto'){
  const n = String(nome || '');
  for (const [re, m] of PAROLE_MED) if (re.test(n)) return m;
  return altrimenti;
}
